'use strict';
let announcementSequence=0;
async function loadAnnouncementReview(){const sequence=++announcementSequence;try{const r=await fetch('/api/announcement-review');if(!r.ok)throw new Error('Announcement review unavailable');const data=await r.json();if(sequence!==announcementSequence)return;$('announcementReviewStatus').textContent=`${data.candidates.length} current candidates / ${data.staleDecisions.length} earlier decisions now outside current candidates. ${data.coverage}`;$('announcementCandidates').innerHTML=data.candidates.map(c=>`<article class="evidence"><p>${esc(c.matchKind)}${c.similarity==null?'':' / token overlap '+c.similarity+'% (not confidence)'}</p><p>Shared terms: ${esc(c.sharedTerms.join(', ')||'Exact headline')}</p><h4>${esc(c.decision?.decision||'NEEDS REVIEW')}</h4>${c.evidence.map(e=>`<p><a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(e.title)}</a><br>${esc(e.sourceName)} / Published ${esc(e.publishedAt)} / hash ${esc(e.contentHash)}</p>`).join('')}<p>${esc(c.reason)}</p><p>${esc(c.limitations)}</p>${c.decision?`<p>Reviewed ${esc(c.decision.reviewedAt)}: ${esc(c.decision.note)} / ${c.decision.history.length} earlier decisions</p>`:''}<form data-announcement="${esc(c.id)}"><label>Relationship<select name="decision"><option value="related">Related announcements</option><option value="distinct">Distinct events / misleading match</option></select></label><label>Review reason<textarea name="note" minlength="5" maxlength="2000" required></textarea></label><button>SAVE REVIEW</button><p role="status"></p></form></article>`).join('')||'<p>No supported candidates found. This does not establish uniqueness; unknown dates and unanchored paraphrases are excluded.</p>';$('announcementCandidates').insertAdjacentHTML('beforeend',data.staleDecisions.length?`<details><summary>EARLIER REVIEWS / ${data.staleDecisions.length} OUTSIDE CURRENT CANDIDATES</summary>${data.staleDecisions.slice(0,50).map(d=>`<article class="evidence"><p>${esc(d.decision)} / ${esc(d.reviewedAt)} / ${esc(d.note)}</p>${d.evidence.map(e=>`<p><a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(e.title)}</a> / saved hash ${esc(e.contentHash)}</p>`).join('')}<p>Historical decision only; current evidence or matcher criteria require review.</p></article>`).join('')}<p>Showing at most 50 historical decisions. Complete history remains in the private review store.</p></details>`:'');$('announcementCandidates').querySelectorAll('[data-announcement]').forEach(form=>form.onsubmit=async event=>{event.preventDefault();try{await companyAction('/api/announcement-review',{id:form.dataset.announcement,decision:form.elements.decision.value,note:form.elements.note.value});await loadAnnouncementReview();}catch(e){form.querySelector('[role="status"]').textContent=e.message;}});}catch(e){$('announcementReviewStatus').textContent=e.message;}}
$('reloadAnnouncementReview').onclick=loadAnnouncementReview;document.querySelector('[data-view="sources"]').addEventListener('click',loadAnnouncementReview);loadAnnouncementReview();
